using System.ComponentModel.DataAnnotations;

namespace DocSummary.Models;

public class SummaryRequest
{
    [Required]
    [MinLength(1)]
    public string DocumentText { get; set; } = string.Empty;
}

namespace DocSummary.Models;

public class SummaryResponse
{
    public string Summary { get; set; } = string.Empty;
    public int OriginalLength { get; set; }
    public int SummaryLength { get; set; }
}

namespace DocSummary.Services;

public interface IDocumentSummaryService
{
    string Summarize(string documentText);
}

namespace DocSummary.Services;

/// <summary>
/// Extractive summarization service that selects the most important sentences
/// from the input document based on word-frequency scoring.
/// </summary>
public class ExtractiveSummaryService : IDocumentSummaryService
{
    private const int MaxSummarySentences = 5;

    private static readonly HashSet<string> StopWords = new(StringComparer.OrdinalIgnoreCase)
    {
        "a", "an", "the", "and", "or", "but", "is", "are", "was", "were",
        "in", "on", "at", "to", "for", "of", "with", "by", "it", "its",
        "this", "that", "from", "as", "be", "been", "being", "have", "has",
        "had", "do", "does", "did", "will", "would", "could", "should",
        "may", "might", "shall", "can", "not", "no", "so", "if", "then",
        "than", "too", "very", "just", "about", "above", "after", "again",
        "all", "also", "am", "any", "because", "before", "between", "both",
        "each", "few", "he", "she", "they", "we", "you", "i", "me", "my",
        "our", "your", "his", "her", "their", "which", "who", "whom",
        "what", "when", "where", "how", "up", "out", "into", "over"
    };

    public string Summarize(string documentText)
    {
        var sentences = SplitIntoSentences(documentText);

        if (sentences.Count <= MaxSummarySentences)
        {
            return documentText.Trim();
        }

        var wordFrequencies = ComputeWordFrequencies(sentences);
        var scoredSentences = ScoreSentences(sentences, wordFrequencies);

        // Pick top-scored sentences but preserve original order
        var topIndices = scoredSentences
            .OrderByDescending(kv => kv.Value)
            .Take(MaxSummarySentences)
            .Select(kv => kv.Key)
            .OrderBy(i => i)
            .ToList();

        return string.Join(" ", topIndices.Select(i => sentences[i].Trim()));
    }

    private static List<string> SplitIntoSentences(string text)
    {
        var sentences = new List<string>();
        int start = 0;

        for (int i = 0; i < text.Length; i++)
        {
            if (text[i] is '.' or '!' or '?')
            {
                // Include the punctuation and any trailing whitespace
                int end = i + 1;
                while (end < text.Length && char.IsWhiteSpace(text[end]))
                    end++;

                var sentence = text[start..end].Trim();
                if (sentence.Length > 0)
                    sentences.Add(sentence);

                start = end;
            }
        }

        // Capture any trailing text without sentence-ending punctuation
        if (start < text.Length)
        {
            var remaining = text[start..].Trim();
            if (remaining.Length > 0)
                sentences.Add(remaining);
        }

        return sentences;
    }

    private static Dictionary<string, double> ComputeWordFrequencies(List<string> sentences)
    {
        var freq = new Dictionary<string, double>(StringComparer.OrdinalIgnoreCase);

        foreach (var sentence in sentences)
        {
            foreach (var word in Tokenize(sentence))
            {
                if (StopWords.Contains(word) || word.Length < 2)
                    continue;

                freq.TryGetValue(word, out double count);
                freq[word] = count + 1;
            }
        }

        // Normalize by max frequency
        if (freq.Count > 0)
        {
            double max = freq.Values.Max();
            foreach (var key in freq.Keys.ToList())
                freq[key] /= max;
        }

        return freq;
    }

    private static Dictionary<int, double> ScoreSentences(
        List<string> sentences,
        Dictionary<string, double> wordFrequencies)
    {
        var scores = new Dictionary<int, double>();

        for (int i = 0; i < sentences.Count; i++)
        {
            double score = 0;
            var words = Tokenize(sentences[i]);

            foreach (var word in words)
            {
                if (wordFrequencies.TryGetValue(word, out double freq))
                    score += freq;
            }

            // Normalize by sentence length to avoid bias toward long sentences
            if (words.Length > 0)
                score /= words.Length;

            scores[i] = score;
        }

        return scores;
    }

    private static string[] Tokenize(string text)
    {
        return text.Split([' ', '\t', '\n', '\r', ',', ';', ':', '"', '\'', '(', ')', '[', ']'],
            StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
    }
}

using DocSummary.Models;
using DocSummary.Services;
using Microsoft.AspNetCore.Mvc;

namespace DocSummary.Controllers;

[ApiController]
[Route("api/[controller]")]
public class SummaryController : ControllerBase
{
    private readonly IDocumentSummaryService _summaryService;

    public SummaryController(IDocumentSummaryService summaryService)
    {
        _summaryService = summaryService;
    }

    [HttpPost]
    public ActionResult<SummaryResponse> Summarize([FromBody] SummaryRequest request)
    {
        var summary = _summaryService.Summarize(request.DocumentText);

        return Ok(new SummaryResponse
        {
            Summary = summary,
            OriginalLength = request.DocumentText.Length,
            SummaryLength = summary.Length
        });
    }
}

